import re
from ipaddress import IPv6Address, ip_address
from six import u
from taf.sbts.oam.sc.rest.interfaces.asir22r3 import ASIR22R3
from taf.sbts.oam.sc.rest.exception import AsirVersionNotSupported


class ConnectionDetails(object):
    def __init__(self, host, port, username, password, secure=False, api_prefix="/api/v1", scope='write'):
        self.protocol = 'https://'
        self.host = host
        self.port = port
        self.secure = secure
        self.scope = scope
        self.username = username
        self.password = password
        self.base_url = '{protocol}{host}:{port}{api_prefix}'. \
            format(protocol=self.protocol, host=ConnectionDetails.normalize_host_for_base_url(self.host),
                   port=self.port, api_prefix=api_prefix)

    @staticmethod
    def normalize_host_for_base_url(host):
        host = host.rstrip("]").lstrip("[")
        try:
            if isinstance(ip_address(u(str(host))), IPv6Address):
                return '[{}]'.format(host)
            else:
                return host
        except (ValueError, TypeError):
            return host

    def make_configuration_host(self, original_endpoint):
        endpoint_match = re.match(r'^http.*localhost', original_endpoint)
        endpoint = original_endpoint.replace(endpoint_match.group(), '')
        original_endpoint = '{base_url}{endpoint}'.format(base_url=self.base_url,
                                                          endpoint=endpoint)
        return original_endpoint


class SupportedASIR(object):
    ASIR_22R3 = ASIR22R3


class ASIRProvider(object):
    @classmethod
    def create_asir(cls, host, port, username, password, asir_version="ASIR_22R3", secure=False, scope='write'):
        asir_type = getattr(SupportedASIR, asir_version, None)

        if not asir_type:
            exception_message = 'Version {} of ASIR is not supported'.format(asir_version)
            raise AsirVersionNotSupported(exception_message)

        con_details = ConnectionDetails(
            host=host, port=port, username=username, password=password, secure=secure, scope=scope)
        asir_webem = asir_type(con_details=con_details)

        return asir_webem
